using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CityCrossingEmission{static CityCrossingEmission(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityCrossingEmission.request"))return;File.Delete("CityCrossingEmission.request");try{Build();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CrossingEmission.txt",e.ToString());Debug.LogException(e);}}
static void Build(){var sc=SceneManager.GetActiveScene();var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();int lights=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length);var materials=all.SelectMany(r=>r.sharedMaterials).Where(m=>m&&(m.shader.name=="Gangstar City/Road Atlas Lit"||m.shader.name=="Gangstar City/Road Detail PNG Atlas")).Distinct().ToArray();if(materials.Length==0)throw new Exception("No matching city road materials found");const string backup="FinalEnvironmentRoadBackup/BeforeCrossingEmission";if(!File.Exists(backup+"/Scene.unity"))EditorSceneManager.SaveScene(sc,backup+"/Scene.unity",true);foreach(var m in materials){if(!File.Exists(backup+"/"+m.name+".mat"))File.Copy(AssetDatabase.GetAssetPath(m),backup+"/"+m.name+".mat");AssetDatabase.ImportAsset(AssetDatabase.GetAssetPath(m.shader),ImportAssetOptions.ForceUpdate);if(!m.HasProperty("_CrossingDotGlow")||ShaderUtil.ShaderHasError(m.shader))throw new Exception("Crossing shader validation failed: "+m.name);m.SetFloat("_CrossingDotGlow",3.0f);m.SetColor("_CrossingDotColor",new Color(1,.42f,.08f,1));m.enableInstancing=true;EditorUtility.SetDirty(m);}
var read=typeof(FinalPathwayRepair).GetMethod("Read",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);var matches=new List<Renderer>();long tris=0;foreach(var r in all){var f=r.GetComponent<MeshFilter>();if(!f||!f.sharedMesh||!r.sharedMaterials.Any(materials.Contains))continue;var data=read.Invoke(null,new object[]{f.sharedMesh});var ty=data.GetType();var uv=(Vector2[])ty.GetField("uv").GetValue(data);tris+=((int[])ty.GetField("ids").GetValue(data)).Length/3;if(uv.Any(p=>Mathf.FloorToInt(p.x/32)==1))matches.Add(r);}if(matches.Count==0)throw new Exception("No slice 1 crossing meshes found");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=c.IsNight;var selected=Selection.activeGameObject?Selection.activeGameObject.GetComponent<Renderer>():null;var chosen=matches.Contains(selected)?selected:matches.Where(r=>r.bounds.size.x<65&&r.bounds.size.z<65&&r.bounds.size.y<1).OrderBy(r=>Vector3.Distance(r.bounds.center,new Vector3(100,30,-100))).FirstOrDefault()??matches.First();var b=chosen.bounds;float height=Mathf.Max(b.size.x,b.size.z)*1.25f;var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);try{c.Apply(true);cap.Invoke(null,new object[]{sc,b.center+Vector3.up*height+Vector3.forward*.02f,b.center,"Crossing-Emission-Night"});c.Apply(false);cap.Invoke(null,new object[]{sc,b.center+Vector3.up*height+Vector3.forward*.02f,b.center,"Crossing-Emission-Day"});}finally{c.Apply(night);}if(lights!=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length)||materials.Any(m=>ShaderUtil.ShaderHasError(m.shader)))throw new Exception("Final crossing verification failed");File.WriteAllText("FinalEnvironmentRoadReview/CrossingEmission.txt","SUCCESS: "+matches.Count+" matching crossing renderers use existing shared materials: "+string.Join(", ",materials.Select(m=>m.name))+". Only bronze panel dot pixels on source slice 1 emit amber; central markings/corner plates excluded. No meshes, materials, textures, renderers, real-time lights or texture samples added. Existing source albedo used as dot mask. Night/day linked. Existing road triangles="+tris+" unchanged; lights="+lights+" unchanged. Shader errors=0. Android device FPS unmeasured.\n"+string.Join("\n",matches.Select(r=>r.name+" "+r.bounds)));}
}
